head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDisplayFormatter]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 데이터 표시를 처리하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 사용자 정의 표시 함수 : 인자로 실제(원본) 데이터를 받고 반환값이 표시 데이터로 적용됨
scwin.fmt_won = function (data) {
    return data + " 원";
};
scwin.fmt_bracket = function (data) {
    return "[" + data + "]";
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼은 inputType=custom + typeGetter(Cell inputType=text). Body 가 MultiLine(2줄).\n[MultiLine] 한 데이터 Row 가 2줄 표시 -> 두 줄은 같은 rowIndex, Column 은 0~3 고유 인덱스 (1줄 col1(0)/col2(1), 2줄 col3(2)/col4(3)).\n[절차] rowIndex / columnIndex / formatter 선택 -> setCellDisplayFormatter 실행.\n[확인] 리턴창에 변경 전·후 표시값 출력 (사용자 함수 반환값이 표시값으로 적용)."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (사용자 정의 함수가 가공할 원본 데이터)
    //  MultiLine 검증 : 한 데이터 Row 가 2줄에 걸쳐 표시되며 두 줄은 동일 rowIndex, Column 은 0~3 고유 인덱스를 가짐.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "1234", "col2": "2234", "col3": "3234", "col4": "4234" },
        { "col1": "1555", "col2": "2555", "col3": "3555", "col4": "4555" }
    ]);

    // target 생성
    //  4개 컬럼 모두 inputType=custom + typeGetter 로 Cell 의 inputType=text 구성
    // ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //  - 1줄 : col1(idx0) / col2(idx1)
    //  - 2줄 : col3(idx2) / col4(idx3)
    //  - 두 줄은 동일 rowIndex, Column 은 줄에 걸쳐 0~3 고유 인덱스
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="col1 (idx0)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="col2 (idx1)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="col3 (idx2)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (idx3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 각 Cell 을 inputType=text (allow-list) 로 구성 (setCellDisplayFormatter 적용 대상)
scwin.target1_typeGetter = function (info) {
    return { id: 'cell_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', options: {} };
};



// 해당 Cell 의 표시값(사용자 정의 함수 등 포맷 적용된 화면값)을 조회
//  getCellDisplayData(rowIndex, columnIndex) : 포맷이 적용된 표시값을 반환
scwin.getCellDisp = function (rowIndex, columnIndex) {
    try {
        return scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    } catch (e) {
        return "(표시값 조회오류)";
    }
};



// setCellDisplayFormatter 실행 : 특정 셀에 사용자 정의 표시 함수를 설정하고 변경 전/후 표시값을 리턴창에 출력
//  MultiLine : 같은 rowIndex 라도 고유 columnIndex(0~3)로 위/아래 Line 의 Cell 을 각각 지정할 수 있다.
scwin.btn_setCellDisplayFormatter_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnIndex = Number(par_columnIndex.getValue());
    let formatter = par_formatter.getValue();

    // 변경 전 표시값
    let before = scwin.getCellDisp(rowIndex, columnIndex);

    // 메소드 실행 (전제 미충족 시 false 반환) - formatter 는 사용자 정의 함수명 문자열
    let ret = scwin.target1.setCellDisplayFormatter(rowIndex, columnIndex, formatter);

    // 화면 갱신 (셀 단위 재렌더)
    try { scwin.target1.refreshCell(rowIndex, columnIndex); } catch (e) {}

    // 변경 후 표시값
    let after = scwin.getCellDisp(rowIndex, columnIndex);

    let changed = (before !== after);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDisplayFormatter(" + rowIndex + ", " + columnIndex + ", '" + formatter + "')"
        + " | 변경 전 표시값 : " + before + " -> 변경 후 표시값 : " + after
        + " | 변경됨 : " + changed
        + (ret === false ? " (전제 미충족 -> 미동작)" : ""));
}
